for (var s in E.us_states)
    E.us_states2code[E.us_states[s]] = s;

E.code2label = function(c){
    c = c.toUpperCase();
    return E.list[c] || c;
};

E.code2adj = function(c){
    c = c.toUpperCase();
    return E.adj_list[c] || c;
};

E.label2code = function(label){
    var c_list = Object.entries(E.list).concat(Object.entries(E.google_list));
    for (var i = 0; i<c_list.length; i++)
    {
        var _c = c_list[i];
        if (_c[1]===label)
            return _c[0];
        var bracket_ind = _c[1].indexOf('(');
        if (bracket_ind!=-1 && _c[1].slice(0, bracket_ind-1)==label)
            return _c[0];
    }
    // Åland Islands case
    for (var k in E.adj_list)
    {
        if (E.adj_list[k].name==label)
            return k;
    }
    var exc = {
        'Macedonia (FYROM)': 'MK',
    };
    return exc[label] || '';
};

var cn_name_alias_map = Object.fromEntries(Object.entries(base_list)
    .filter(function(e){ return e[1].cn_name_alias; })
    .flatMap(function(e){
        return e[1].cn_name_alias.map(function(alias){
            return [alias, e[0]];
        });
    }));

E.cnlabel2code = function(label){
    if (cn_name_alias_map[label])
        return cn_name_alias_map[label];
    for (var i in E.cn_list)
    {
        if (E.cn_list[i]===label)
            return i;
    }
    return '';
};

E.alpha3_to_alpha2 = function alpha3_to_alpha2(a3){
    a3 = a3.toUpperCase();
    var alpha2 = Object.keys(alpha_3_list);
    var alpha3 = Object.values(alpha_3_list);
    var a2 = alpha2[alpha3.indexOf(a3)];
    return a2||a3;
};

E.mixed2code = function(mixed){
    if (!mixed)
        return;
    if (/^[A-Z]{2}$/.test(mixed))
        return mixed;
    if (mixed.length==2)
        return mixed.toUpperCase();
    for (var ccode in E.list)
    {
        if (E.list[ccode].toLowerCase()==mixed.toLowerCase())
            return ccode;
    }
    if (mixed.length==3)
    {
        for (var acode in alpha_3_list)
        {
            if (alpha_3_list[acode].toLowerCase()==mixed.toLowerCase())
                return acode;
        }
    }
    return mixed;
};

E.www2code = function(c){
    return c=='UK' ? 'GB' : c=='uk' ? 'gb' : c; };

E.code2www = function(c){
    return c=='GB' ? 'UK' : c=='gb' ? 'uk' : c; };

E.gl2uule = function(gl){
    gl = E.www2code(gl.toUpperCase());
    // Google doesn't recognize uule="North Macedonia". This name is kept in
    // E.google_list though to be equal to official label in Google settings
    // (https://www.google.com/preferences).
    if (gl=='MK')
        return 'Macedonia';
    return E.google_list[gl] || gl;
};

var uule_to_gl_map = {};
for (var gl_code in E.google_list)
{
    gl_code = E.www2code(gl_code);
    var uule_country = E.google_list[gl_code].toLowerCase();
    uule_to_gl_map[uule_country] = gl_code;
}
E.uule2gl = function(uule){
    uule = uule.toLowerCase();
    if (uule=='macedonia')
        return 'MK';
    return E.www2code(uule_to_gl_map[uule]);
};

var gs1_countries_rlist = {};
